#include "presentation.hpp"
#include <fstream>
#include <iostream>
using namespace fa;
namespace {
int checks=0;
void check(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
bool has(const std::vector<SimpleFinding>& findings,std::string_view text){for(const auto& f:findings)if((f.topic+f.title+f.value+f.detail).find(text)!=std::string::npos)return true;return false;}
Result fromJson(const Json& j){Result r;r.provenance=j["provenance"];r.generation=j["generation"];for(const auto& f:j["fields"])r.fields.push_back({f["category"],f["name"],f["source"],f["warning"],f["value"],f["raw"],{},{}});return r;}
}
int wmain(int argc,wchar_t** argv){try{
 check(argc==2||argc==3,"Expected fixtures and optional real analysis report");
 std::atomic_bool cancel=false;Options options;options.useParser=false;options.useC2pa=false;
 auto clean=analyze(fs::path(argv[1])/L"clean.png",options,cancel);auto before=clean.json();auto plain=simpleFindings(clean);
 check(plain.size()==1&&has(plain,"No additional clues recovered"),"Plain image gets an honest empty finding, not a properties replica");
 check(!has(plain,"SHA-256")&&!has(plain,"Filesystem creation")&&!has(plain,"PNG width"),"Routine file properties omitted");
 check(clean.json()==before,"Simple projection leaves original evidence unchanged");
 auto broken=analyze(fs::path(argv[1])/L"bad-crc.png",options,cancel);auto warnings=simpleFindings(broken);
 check(has(warnings,"CRC mismatch"),"Corruption remains visible in Simple");
 auto metadata=analyze(fs::path(argv[1])/L"metadata.png",options,cancel);auto generated=simpleFindings(metadata);
 check(has(generated,"Prompt")&&has(generated,"Seed"),"Recognized generation parameters surfaced");
 check(!has(generated,"AUTOMATIC1111-compatible parameters"),"Combined parameter blob does not duplicate interpreted settings");
 Result r;r.fields.push_back({"Analysis diagnostics","ExifTool:Software","ExifTool","","Scanner software",nullptr,{},{}});r.fields.push_back({"XMP","XMP:CreatorTool","ExifTool","","Embedded editor",nullptr,{},{}});r.fields.push_back({"PNG text","Software","PNG","","Embedded editor",nullptr,{},{}});
 auto claims=simpleFindings(r);check(has(claims,"Embedded editor")&&!has(claims,"Scanner software"),"Only actual embedded software claims selected");
 r.blocks.push_back({"zzZZ","Unknown chunk; CRC valid","",8,42});check(has(simpleFindings(r),"Unrecognized block"),"Unknown resources surfaced without labelling them tampered");
 r.status="cancelled";check(has(simpleFindings(r),"Incomplete analysis"),"Cancelled results do not imply a complete metadata search");
 r.provenance={{"detected",true},{"manifests",Json::array()},{"verification",{{"performed",false},{"signature_integrity","valid"},{"certificate_trust","trusted_by_bundled_snapshot"}}}};
 auto unverified=simpleFindings(r);check(has(unverified,"Not independently verified")&&has(unverified,"Not evaluated")&&!has(unverified,"Trusted by bundled certificate list"),"Unperformed validation cannot become a verified success");
 r.provenance["verification"]={{"performed",true},{"signature_integrity","valid"},{"content_binding","failed"},{"manifest_integrity","failed"},{"certificate_trust","untrusted_or_invalid"}};
 auto tampered=simpleFindings(r);check(has(tampered,"Failed - provenance or file integrity problem")&&has(tampered,"Signer untrusted or invalid"),"File integrity and signer trust remain separate");
 r.provenance["manifests"]=Json::array({{{"id","new"},{"actions",Json::array({{{"action","c2pa.converted"},{"description","Converted to PNG"}}})}},{{"id","old"},{"actions",Json::array({{{"action","c2pa.created"},{"description","Generated by fixture"}}})}}});
 r.provenance["history_order"]=Json::array({"old","new"});r.provenance["active_manifest"]="new";r.provenance["relationships"]=Json::array({{{"manifest","new"},{"ingredient_manifest","old"},{"relationship","parentOf"},{"resolved",true}}});
 r.provenance["ai_claims"]=Json::array({{{"action",{{"action","c2pa.created"},{"description","Generated by fixture"}}}}});
 auto history=simpleFindings(r);size_t old=history.size(),current=history.size();for(size_t i=0;i<history.size();++i){if(history[i].title=="Record 1")old=i;if(history[i].title=="Record 2 (current)")current=i;}
 check(old<current&&current<history.size()&&history[current].detail.find("Source: record 1")!=std::string::npos,"History follows source links rather than storage order");
 check(has(history,"Prompt / model / seed")&&has(history,"AI generation claim"),"Missing parameters do not erase provenance claims");
 if(argc==3){std::ifstream input(argv[2]);Json report=Json::parse(input);auto real=fromJson(report["files"][0]);auto findings=simpleFindings(real);
  check(has(findings,"Created by Google Generative AI.")&&has(findings,"Applied imperceptible SynthID")&&has(findings,"Added visible watermark"),"Gemini's useful creation and processing claims retained");
  check(has(findings,"Signature and file binding passed")&&has(findings,"Trusted by bundled certificate list"),"Gemini integrity and trust legible separately");
  check(has(findings,"No independent watermark detection")&&has(findings,"Prompt / model / seed"),"Gemini claim limitations retained");
  check(findings.size()<15&&!has(findings,"urn:c2pa:")&&!has(findings,"NewUUID"),"Gemini Simple view compact and free of raw identifiers and diagnostics");
  for(const auto& f:findings)std::cout<<f.topic<<" | "<<f.title<<" | "<<f.value<<"\n";
 }
 std::cout<<"PASS: "<<checks<<" presentation assertions\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" presentation assertions: "<<e.what()<<"\n";return 1;}}
